package com.javafundamentals;

public class Fundamental {
	char r;
	byte b;
	int a;
	short c;
	double d;
	long e;
	boolean l;
	float f;
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Fundamental g=new Fundamental();
        System.out.println("char default value :"+g.r);
        System.out.println("byte default value : "+g.b);
        System.out.println("int default value : "+g.a);
        System.out.println("short default value : "+g.c);
        System.out.println(" double default value : "+g.d);
        System.out.println("long default value : "+g.e);
        System.out.println("boolean default value : "+g.l);
        System.out.println("float default value : "+g.f);
        
	}

}
